window.CubeApiDocs.define("api-Data_Management-签入应用层用户数据",{"id":"api-Data_Management-签入应用层用户数据","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Data_Management-签入应用层用户数据\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">数据管理 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">User - 签入应用层用户数据\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/app/user/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>使用账号信息签入应用层用户，并将用户与当前访问令牌关联。使用 \u003ccode>POST\u003c/code> 提交 JSON，\u003ccode>name\u003c/code> 是用户唯一识别串，\u003ccode>password\u003c/code> 使用密码的 MD5 摘要。 \u003cp>已有用户签入时设置 \u003ccode>register=false\u003c/code>，注册新用户时设置为 \u003ccode>true\u003c/code>。检查应答的 \u003ccode>valid\u003c/code>，确认通过后再使用 \u003ccode>user\u003c/code> 中的用户资料。设备信息须与实际客户端一致。\u003c/p>\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>以已有账号签入\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"developer@example.com\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"password\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"e10adc3949ba59abbe56e057f20f883e\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"device\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"web-client\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"platform\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"Web\"\u003c/span>\n    \u003cspan class=\"token punctuation\">}\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"register\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">false\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdetails class=\"example lazy-example\">\u003csummary>完整请求示例\u003c/summary>\u003ctemplate>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>http\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>POST http://211.157.179.37:7010/app/user/UQYrEcbPaZhHSBvJippdpPrwvIfvuPlG\n\u003cspan class=\"token header\">\u003cspan class=\"token header-name keyword\">Content-Type\u003c/span>\u003cspan class=\"token punctuation\">:\u003c/span> \u003cspan class=\"token header-value\">application/json\u003c/span>\u003c/span>\n\u003cspan class=\"token application-json\">\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"developer@example.com\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"password\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"e10adc3949ba59abbe56e057f20f883e\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"device\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"web-client\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"platform\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"Web\"\u003c/span>\n    \u003cspan class=\"token punctuation\">}\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"register\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">false\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/template>\u003c/details>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>name\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>用户名，确定用户的唯一识别串。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>password\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>用户密码的散列码，使用 MD5 散列。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>device\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>客户端设备信息。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>device.name\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>设备名称。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>device.platform\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>设备平台描述。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>address\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>用户地址信息。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>register\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>是否使用该用户信息注册为新用户。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"valid\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">true\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"user\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"channel\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"displayName\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"avatar\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"phoneNumber\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"email\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"registerTime\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">0\u003c/span> \n    \u003cspan class=\"token punctuation\">}\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>valid\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>是否有效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>user\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003c/td>\u003ctd>\u003cp>签入的用户数据。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.name\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>用户名。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.channel\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>客户端渠道标识。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.displayName\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>用户显示名。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.avatar\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>用户头像。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.phoneNumber\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>用户手机号码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.email\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>用户电子邮箱。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>user.registerTime\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>注册时间戳。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>操作发生错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>令牌无效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>403\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
